// Start a Stripe Checkout for any purchasable item; falls back to email if payments are off
async function startCheckout(item, extra = {}) {
  // exposed on window so member-side pages can trigger checkout
  try {
    const res = await fetch("/api/stripe", {
      method: "POST",
      headers: { "Content-Type": "application/json", Authorization: "Bearer " + getMemberToken() },
      body: JSON.stringify({ item, ...extra }),
    });
    const d = await res.json();
    if (res.status === 401) { alert("Sign in first, then purchase."); return false; }
    // Elite sold out between page load and checkout — don't fall through to the mailto
    if (res.status === 409 && d.elite_full) { alert(d.message || "Elite is full right now."); return false; }
    if (!res.ok) throw new Error(d.error || "Checkout failed");
    window.location.href = d.url;
    return true;
  } catch (e) {
    window.location.href = "mailto:groundup@drginamerritt.net?subject=" + encodeURIComponent("GroundUp purchase: " + item);
    return false;
  }
}
if (typeof window !== "undefined") window.startCheckout = (item, extra) => startCheckout(item, extra);
// datetime-local inputs speak LOCAL wall-clock time; we store UTC ISO strings.
// Always convert at the boundary — feeding an ISO string's first 16 chars back
// into the input shifts the time by the UTC offset on every render.
// "Add to Google Calendar" — no integration needed, just Google's template URL.
// Opens a prefilled event the person saves to their own calendar with one click.
function gcalUrl(title, startIso, minutes = 60, details = "", location = "") {
  const fmt = (d) => new Date(d).toISOString().replace(/[-:]|\.\d{3}/g, "");
  const start = new Date(startIso);
  const end = new Date(start.getTime() + minutes * 60000);
  const q = new URLSearchParams({ action: "TEMPLATE", text: title, dates: `${fmt(start)}/${fmt(end)}`, details, location });
  return `https://calendar.google.com/calendar/render?${q}`;
}

function toLocalInput(iso) {
  if (!iso) return "";
  const d = new Date(iso);
  if (isNaN(d)) return "";
  const p = (n) => String(n).padStart(2, "0");
  return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}T${p(d.getHours())}:${p(d.getMinutes())}`;
}

